import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import UnoCSS from 'unocss/vite';

/**
 * HOST/PORT are injected by portless (`pnpm dev`) and by the platform start
 * command; the defaults only matter for a plain `pnpm dev` without portless.
 * The dev server proxies /api to the backend so the browser always uses
 * same-origin relative URLs (docs/architecture.md §3).
 */
const apiTarget = process.env.API_TARGET || 'http://127.0.0.1:4102';

export default defineConfig({
  plugins: [react(), UnoCSS()],
  server: {
    host: process.env.HOST || '127.0.0.1',
    port: Number(process.env.PORT || 4101),
    strictPort: true,
    proxy: {
      '/api': {
        target: apiTarget,
        changeOrigin: false,
      },
    },
  },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
});

import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronDown, LogOut } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';
import { auth as authCopy } from '../contracts/copy';
import { cx } from '../utils/cx';
import { Button } from './Button';
import { Dialog } from './Dialog';
import { Menu } from './Menu';

/**
 * Account menu (REQ-1-2, docs/architecture.md §7).
 *
 * The trigger is exactly one button whose accessible name is "Account menu".
 * The panel contains a single link named "Sign out" (plus the navigation entries
 * of the signed-in shell). Activating "Sign out" opens a dialog named "Sign out"
 * with the buttons "Confirm sign out" and "Cancel".
 */
export function AccountMenu() {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const [confirmOpen, setConfirmOpen] = useState(false);

  if (!user) return null;
  const initial = user.username.slice(0, 1).toUpperCase();

  return (
    <>
      <Menu
        trigger={({ open, toggle, triggerRef }) => (
          <button
            ref={triggerRef}
            type="button"
            aria-label={authCopy.accountMenu}
            aria-haspopup="true"
            aria-expanded={open}
            onClick={toggle}
            className={cx('flex items-center gap-1 bg-transparent border-none cursor-pointer p-0')}
          >
            <span className="avatar" aria-hidden="true">
              {initial}
            </span>
            <ChevronDown size={14} aria-hidden="true" className="text-muted" />
          </button>
        )}
      >
        {({ close }) => (
          <>
            <p className="px-2 py-1 m-0 text-xs text-muted">
              Signed in as <span className="font-600 text-fg">{user.username}</span>
            </p>
            <hr className="menu-item-separator" />
            <Link className="menu-item" to="/settings/organizations" onClick={close}>
              {authCopy.yourOrganizations}
            </Link>
            <Link className="menu-item" to="/settings/repositories" onClick={close}>
              {authCopy.yourRepositories}
            </Link>
            <Link className="menu-item" to="/settings/profile" onClick={close}>
              {authCopy.settings}
            </Link>
            <hr className="menu-item-separator" />
            <a
              className="menu-item"
              href="#sign-out"
              aria-haspopup="dialog"
              onClick={(event) => {
                event.preventDefault();
                close();
                setConfirmOpen(true);
              }}
            >
              <LogOut size={14} aria-hidden="true" />
              {authCopy.signOut}
            </a>
          </>
        )}
      </Menu>

      <Dialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title={authCopy.signOut}
        description={authCopy.signOutDialogDescription}
        footer={
          <>
            <Button
              variant="default"
              onClick={() => {
                setConfirmOpen(false);
              }}
            >
              {authCopy.cancel}
            </Button>
            <Button
              variant="primary"
              onClick={async () => {
                await signOut();
                setConfirmOpen(false);
                navigate('/');
              }}
            >
              {authCopy.confirmSignOut}
            </Button>
          </>
        }
      />
    </>
  );
}

export default AccountMenu;

import { useState } from 'react';
import type { ReactNode } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { GitBranch } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';
import { APP_NAME, auth as authCopy, shell as shellCopy } from '../contracts/copy';
import { AccountMenu } from './AccountMenu';

/**
 * Application shell (docs/architecture.md §7).
 *
 * Signed out: brand + "Sign in" / "Sign up" entries.
 * Signed in: brand + global search + the account menu.
 * Business modules add their repository navigation inside the page content.
 */
export function AppShell({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');

  return (
    <div className="min-h-screen bg-canvas text-fg font-sans">
      <header className="border-b border-solid border-border bg-subtle">
        <div className="mx-auto flex w-full max-w-5xl items-center gap-4 px-4 py-3">
          <Link to="/" className="flex items-center gap-2 text-fg no-underline font-600">
            <GitBranch size={20} aria-hidden="true" />
            {APP_NAME}
          </Link>

          <form
            role="search"
            className="flex-1 max-w-md"
            onSubmit={(event) => {
              event.preventDefault();
              const trimmed = query.trim();
              navigate(trimmed ? `/search?q=${encodeURIComponent(trimmed)}` : '/search');
            }}
          >
            <input
              type="search"
              aria-label={shellCopy.search}
              placeholder={shellCopy.search}
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              className="form-input w-full"
            />
          </form>

          <nav className="ml-auto flex items-center gap-3">
            {loading ? null : user ? (
              <AccountMenu />
            ) : (
              <>
                <Link className="text-sm text-accent no-underline" to="/login">
                  {authCopy.signIn}
                </Link>
                <Link className="text-sm text-accent no-underline" to="/register">
                  {authCopy.signUp}
                </Link>
              </>
            )}
          </nav>
        </div>
      </header>

      <main>{children}</main>
    </div>
  );
}

export default AppShell;

import { Navigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import type { ReactNode } from 'react';

/**
 * Route guard for protected pages.
 *
 * It redirects to the account-access page while the session is unknown and when
 * the visitor is signed out, so browser back navigation to a protected page
 * after signing out restores the unauthenticated state (REQ-1-2).
 */
export function RequireAuth({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) {
    return (
      <div className="page-shell">
        <p className="text-muted">Loading…</p>
      </div>
    );
  }
  if (!user) return <Navigate to="/login" replace />;
  return <>{children}</>;
}

export default RequireAuth;

import { Link } from 'react-router-dom';
import { useAuth } from '../../auth/AuthContext';
import { APP_NAME, auth as authCopy } from '../../contracts/copy';

/** Home page: the entry point every scenario starts from. */
export function HomePage() {
  const { user, loading } = useAuth();
  return (
    <div className="page-shell">
      <h1 className="page-title">{APP_NAME}</h1>
      <p className="text-muted mt-2">
        A simplified collaboration platform: accounts, organisations, repositories, code, issues and pull
        requests.
      </p>

      {loading ? null : user ? (
        <p className="mt-4">
          Signed in as <strong>{user.username}</strong>.
        </p>
      ) : (
        <p className="mt-4 flex gap-3">
          <Link className="btn-primary" to="/login">
            {authCopy.signIn}
          </Link>
          <Link className="btn-default" to="/register">
            {authCopy.signUp}
          </Link>
        </p>
