export default HomePage;

import { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { ApiError } from '../../api/client';
import { useAuth } from '../../auth/AuthContext';
import { ErrorAlert, SuccessAlert } from '../../components/Alerts';
import { Button } from '../../components/Button';
import { TextField } from '../../components/TextField';
import { auth as authCopy } from '../../contracts/copy';

interface LocationState {
  registered?: boolean;
  email?: string;
}

/**
 * Account-access page, sign-in form (REQ-1-1-2).
 * The links to registration and password recovery required by REQ-1-1-1 /
 * REQ-1-1-3 are part of this page.
 */
export function SignInPage() {
  const { signIn } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const state = (location.state ?? {}) as LocationState;

  const [identifier, setIdentifier] = useState(state.email ?? '');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<ApiError | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitting(true);
    setError(null);
    try {
      await signIn(identifier, password);
      navigate('/');
    } catch (caught) {
      setError(caught instanceof ApiError ? caught : new ApiError(0, { code: 'unknown', message: 'Something went wrong' }));
      // A failed sign-in must not keep the submitted password in the form.
      setPassword('');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="mx-auto w-full max-w-sm mt-10">
      <h1 className="page-title text-center">Sign in to {`SimpliHub`}</h1>

      <div className="app-card p-4 mt-4">
        {state.registered ? <SuccessAlert>Account created. Sign in with your new credentials.</SuccessAlert> : null}
        {error?.generalErrors().map((message) => (
          <ErrorAlert key={message}>{message}</ErrorAlert>
        ))}
        {error?.fieldError('identifier') ? <ErrorAlert>{error.fieldError('identifier')}</ErrorAlert> : null}

        <form onSubmit={onSubmit} noValidate>
          <TextField
            label={authCopy.usernameOrEmail}
            name="identifier"
            autoComplete="username"
            value={identifier}
            error={error?.fieldError('identifier')}
            onChange={(event) => setIdentifier(event.target.value)}
          />
          <TextField
            label={authCopy.password}
            name="password"
            type="password"
            autoComplete="current-password"
            value={password}
            error={error?.fieldError('password')}
            onChange={(event) => setPassword(event.target.value)}
          />
          <Button type="submit" variant="primary" className="w-full" disabled={submitting}>
            {authCopy.signIn}
          </Button>
        </form>

        <p className="mt-4 flex justify-between text-sm m-0">
          <Link className="text-accent" to="/register">
            {authCopy.createAccount}
          </Link>
          <Link className="text-accent" to="/password-reset">
            {authCopy.forgotPassword}
          </Link>
        </p>
      </div>
    </div>
  );
}

export default SignInPage;

import { Route, Routes } from 'react-router-dom';
import { RequireAuth } from './components/RequireAuth';
import { HomePage } from './features/home/HomePage';
import { SignInPage } from './features/auth/SignInPage';
import { SignUpPage } from './features/auth/SignUpPage';
import { PasswordResetPlaceholderPage } from './features/auth/PasswordResetPlaceholderPage';
import { SearchPage } from './features/search/SearchPage';
import { SettingsPage } from './features/settings/SettingsPage';
import { NotFoundPage } from './features/NotFoundPage';

/**
 * Application routes (docs/architecture.md §7).
 *
 * Business modules add their routes here:
 *   /:owner/:repo(/*)  — M3/M4/M5/M6
 *   /orgs/:org(/*)     — M2
 *   /settings/*        — M1
 */
export const appRoutes = (
  <Routes>
    <Route path="/" element={<HomePage />} />
    <Route path="/login" element={<SignInPage />} />
    <Route path="/register" element={<SignUpPage />} />
    <Route path="/password-reset" element={<PasswordResetPlaceholderPage />} />
    <Route path="/search" element={<SearchPage />} />
    <Route
      path="/settings/*"
      element={
        <RequireAuth>
          <SettingsPage />
        </RequireAuth>
      }
    />
    <Route path="*" element={<NotFoundPage />} />
  </Routes>
);

export default appRoutes;

import { Link } from 'react-router-dom';
import { auth as authCopy } from '../../contracts/copy';

/**
