export default App;

/** Shared helpers for the Playwright specs. */
import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';

let counter = 0;

/**
 * Unique token for objects created by a test run. The requirements mandate
 * unique-suffix objects and forbid global count assertions, and the seed data is
 * never reset per test.
 */
export function uniqueToken(prefix: string): string {
  counter += 1;
  const random = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now().toString(36)}-${counter}-${random}`.toLowerCase();
}

export const SEED_ACCOUNT = {
  username: 'alice-dev',
  email: 'alice.dev@example.test',
  password: 'Valid-password-123!',
};

/** Register a fresh account through the UI; returns its credentials. */
export async function registerAccount(page: Page) {
  const username = uniqueToken('pw-user').slice(0, 39);
  const email = `${username}@example.test`;
  const password = 'Valid-password-123!';

  await page.goto('/register');
  await page.getByLabel('Username', { exact: true }).fill(username);
  await page.getByLabel('Email', { exact: true }).fill(email);
  await page.getByLabel('Password', { exact: true }).fill(password);
  await page.getByLabel('Confirm password', { exact: true }).fill(password);
  await page.getByRole('checkbox', { name: 'Agree to the terms' }).check();
  await page.getByRole('button', { name: 'Create account' }).click();

  // Successful registration lands on the sign-in page.
  await expect(page).toHaveURL(/\/login$/);
  return { username, email, password };
}

/** Sign in through the UI. */
export async function signIn(page: Page, identifier: string, password: string) {
  await page.goto('/login');
  await page.getByLabel('Username or email', { exact: true }).fill(identifier);
  await page.getByLabel('Password', { exact: true }).fill(password);
  await page.getByRole('button', { name: 'Sign in' }).click();
}

/**
 * Foundation smoke suite: the session closure that every business module
 * consumes (REQ-1-1-1 registration, REQ-1-1-2 sign-in, REQ-1-2 sign-out).
 *
 * Assertions use roles and the exact accessible names from the copy contract.
 */
import { expect, test } from '@playwright/test';
import { auth as authCopy, errors as errorCopy } from '../frontend/src/contracts/copy';
import { registerAccount, SEED_ACCOUNT, signIn, uniqueToken } from './helpers';

test.describe('session closure', () => {
  test('register -> sign in -> account menu -> sign out', async ({ page }) => {
    const account = await registerAccount(page);

    // Registration must not sign the visitor in.
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toHaveCount(0);
    await expect(page.getByRole('link', { name: authCopy.signIn }).first()).toBeVisible();

    // The sign-in form is prefilled with the registered email (input is retained).
    await expect(page.getByLabel(authCopy.usernameOrEmail, { exact: true })).toHaveValue(account.email);
    await page.getByLabel(authCopy.password, { exact: true }).fill(account.password);
    await page.getByRole('button', { name: authCopy.signIn }).click();

    // Signed in: the account menu is present with exactly one trigger button.
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toHaveCount(1);
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toBeVisible();

    // The session survives a reload.
    await page.reload();
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toBeVisible();

    // Sign out requires confirmation.
    await page.getByRole('button', { name: authCopy.accountMenu }).click();
    await page.getByRole('link', { name: authCopy.signOut }).click();
    const dialog = page.getByRole('dialog', { name: authCopy.signOut });
    await expect(dialog).toBeVisible();
    await expect(dialog.getByRole('button', { name: authCopy.confirmSignOut })).toBeVisible();
    await expect(dialog.getByRole('button', { name: authCopy.cancel })).toBeVisible();

    await dialog.getByRole('button', { name: authCopy.confirmSignOut }).click();
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toHaveCount(0);
    await expect(page.getByRole('link', { name: authCopy.signIn }).first()).toBeVisible();

    // The signed-out session cannot be restored by reloading a protected page.
    await page.goto('/settings/profile');
    await expect(page).toHaveURL(/\/login$/);
  });

  test('cancelling the sign-out dialog keeps the session', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toBeVisible();

    await page.getByRole('button', { name: authCopy.accountMenu }).click();
    await page.getByRole('link', { name: authCopy.signOut }).click();
    await page.getByRole('dialog', { name: authCopy.signOut }).getByRole('button', { name: authCopy.cancel }).click();

    await expect(page.getByRole('dialog', { name: authCopy.signOut })).toHaveCount(0);
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toBeVisible();
  });

  test('sign-in with a wrong password shows the generic message and no session', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, 'Wrong-password-123!');
    await expect(page.getByRole('alert').filter({ hasText: errorCopy.invalidCredentials })).toBeVisible();
    await expect(page.getByRole('button', { name: authCopy.accountMenu })).toHaveCount(0);
    // The submitted password is not kept in the form.
    await expect(page.getByLabel(authCopy.password, { exact: true })).toHaveValue('');
  });
});

test.describe('registration validation', () => {
  test('reports every invalid field in one submission and keeps username and email', async ({ page }) => {
    const username = `-${uniqueToken('bad').slice(0, 20)}`;
    const email = 'not-an-email';

    await page.goto('/register');
    await page.getByLabel(authCopy.username, { exact: true }).fill(username);
    await page.getByLabel(authCopy.email, { exact: true }).fill(email);
    await page.getByLabel(authCopy.password, { exact: true }).fill('short');
    await page.getByLabel(authCopy.confirmPassword, { exact: true }).fill('different');
    await page.getByRole('button', { name: authCopy.createAccountButton }).click();

    for (const message of [
      errorCopy.usernameFormatInvalid,
      errorCopy.emailFormatInvalid,
      errorCopy.passwordRequirements,
      errorCopy.passwordConfirmationMismatch,
      errorCopy.termsRequired,
    ]) {
      await expect(page.getByText(message, { exact: true })).toBeVisible();
    }
    await expect(page.getByLabel(authCopy.username, { exact: true })).toHaveValue(username);
    await expect(page.getByLabel(authCopy.email, { exact: true })).toHaveValue(email);
    await expect(page).toHaveURL(/\/register$/);
  });

  test('rejects a duplicate username with the exact message', async ({ page }) => {
    await page.goto('/register');
    await page.getByLabel(authCopy.username, { exact: true }).fill(SEED_ACCOUNT.username);
    await page.getByLabel(authCopy.email, { exact: true }).fill(`${uniqueToken('dupe')}@example.test`);
    await page.getByLabel(authCopy.password, { exact: true }).fill(SEED_ACCOUNT.password);
    await page.getByLabel(authCopy.confirmPassword, { exact: true }).fill(SEED_ACCOUNT.password);
    await page.getByRole('checkbox', { name: authCopy.agreeToTerms }).check();
    await page.getByRole('button', { name: authCopy.createAccountButton }).click();

    await expect(page.getByText(errorCopy.usernameExists, { exact: true })).toBeVisible();
    await expect(page).toHaveURL(/\/register$/);
  });
});

