import { api } from '../../api/client';

export interface ViewerPermission { repository: string|null; organization: string|null; canView: boolean }
export interface RepoFileEntry { name: string; type: 'file'|'directory'; path: string; url: string }
export interface ForkSource { owner: string|null; name: string }
export interface RepositoryDetail {
  owner: string; name: string; description: string; visibility: 'public'|'private';
  defaultBranch: string|null; forkSource: ForkSource|null; files: RepoFileEntry[];
  updatedAt: string; viewerPermission: ViewerPermission;
}
export interface RepositorySummary { owner: string; name: string; description: string; visibility: 'public'|'private'; updatedAt: string; path: string }
export interface Namespace { name: string; kind: 'user'|'org' }

export const repoApi = {
  detail: (owner, name) => api.get<{repository: RepositoryDetail}>(`/api/repos/${encodeURIComponent(owner)}/${encodeURIComponent(name)}`).then(r => r.repository),
  search: (q) => api.get<{repositories: RepositorySummary[]}>(`/api/search/repositories?q=${encodeURIComponent(q)}`).then(r => r.repositories),
  namespaces: () => api.get<{namespaces: Namespace[]}>('/api/me/namespaces').then(r => r.namespaces),
  create: (input) => api.post<{repository: RepositoryDetail}>('/api/repos', input).then(r => r.repository),
  fork: (owner, name, input) => api.post<{repository:RepositoryDetail}>(`/api/repos/${e(owner)}/${e(name)}/fork`, input).then(r=>r.repository),
  changeVisibility: (owner, name, visibility) => api.patch<{repository:RepositoryDetail}>(`/api/repos/${e(owner)}/${e(name)}`, { visibility }).then(r=>r.repository),
};
