/**
 * Repository module API client (REQ-3).
 *
 * Same-origin relative requests through the shared `api` client, so every failure
 * arrives as the uniform `ApiError` payload (docs/architecture.md §3) and forms can
 * render field errors.
 */
import { api, ApiError } from '../../api/client';

export type Visibility = 'public' | 'private';

export interface ViewerPermission {
  repository: string | null;
  organization: string | null;
  canView: boolean;
}

export interface RepositoryFileEntry {
  name: string;
  type: 'file' | 'directory';
  path: string;
  url: string;
}

export interface ForkSource {
  owner: string | null;
  name: string;
}

export interface RepositoryDetail {
  owner: string;
  name: string;
  description: string;
  visibility: Visibility;
  defaultBranch: string | null;
  forkSource: ForkSource | null;
  files: RepositoryFileEntry[];
  updatedAt: string;
  viewerPermission: ViewerPermission;
}

export interface RepositorySummary {
  owner: string;
  name: string;
  description: string;
  visibility: Visibility;
  updatedAt: string;
  path: string;
}

export interface Namespace {
  name: string;
  kind: 'user' | 'org';
}

export interface CreateRepositoryInput {
  owner: string;
  name: string;
  description?: string;
  visibility: Visibility;
  initReadme?: boolean;
}

export interface ForkRepositoryInput {
  owner: string;
  name?: string;
  visibility?: Visibility;
}

const encode = (value: string) => encodeURIComponent(value);
export const repoPath = (owner: string, name: string) => `/${owner}/${name}`;

/** Field errors by form field name + the problems that belong to no field. */
export function formErrors(error: unknown): { fields: Record<string, string>; general: string[] } {
  const fields: Record<string, string> = {};
  const general: string[] = [];
  if (error instanceof ApiError) {
    for (const problem of error.errors) {
      if (problem.field) fields[problem.field] ??= problem.message;
      else general.push(problem.message);
    }
    if (!error.errors.length) general.push(error.message);
  } else {
    general.push('Something went wrong');
  }
  return { fields, general };
}

export const repoApi = {
  search: (query: string) =>
    api
      .get<{ repositories: RepositorySummary[] }>(`/api/search/repositories?q=${encodeURIComponent(query)}`)
      .then((result) => result.repositories),
  detail: (owner: string, name: string) =>
    api
      .get<{ repository: RepositoryDetail }>(`/api/repos/${encode(owner)}/${encode(name)}`)
      .then((result) => result.repository),
  namespaces: () => api.get<{ namespaces: Namespace[] }>('/api/me/namespaces').then((result) => result.namespaces),
  create: (input: CreateRepositoryInput) =>
    api.post<{ repository: RepositoryDetail }>('/api/repos', input).then((result) => result.repository),
  fork: (owner: string, name: string, input: ForkRepositoryInput) =>
    api
      .post<{ repository: RepositoryDetail }>(`/api/repos/${encode(owner)}/${encode(name)}/fork`, input)
      .then((result) => result.repository),
  changeVisibility: (owner: string, name: string, visibility: Visibility) =>
    api
      .patch<{ repository: RepositoryDetail }>(`/api/repos/${encode(owner)}/${encode(name)}`, { visibility })
      .then((result) => result.repository),
};

/**
 * Clone addresses shown in the "Code" popover. They are display values only: the
 * product implements no external Git protocol (REQ-3-2-2 description), and the
 * HTTPS form may omit `.git` while the SSH form always carries the colon and the
 * `.git` suffix (REQ-3-2-3).
 */
export function cloneValues(owner: string, name: string): { https: string; ssh: string } {
  const { host, hostname, protocol } = window.location;
  const scheme = protocol === 'https:' ? 'https' : 'http';
  return {
    https: `${scheme}://${host}/${owner}/${name}.git`,
    ssh: `git@${hostname}:${owner}/${name}.git`,
  };
}

