/**
 * Visible repositories of one namespace (owner) — the personal/organisation
 * repository list entry point of REQ-3. Unknown namespaces yield an empty list and
 * `owner: null`; a private repository of the namespace is only listed for viewers
 * that satisfy the shared access rule.
 */
export function listNamespaceRepositories(db, user, ownerName) {
  const namespace = resolveNamespace(db, ownerName);
  if (!namespace) return { owner: null, repositories: [] };
  const column = namespace.kind === 'user' ? 'owner_user_id' : 'owner_org_id';
  const id = namespace.kind === 'user' ? namespace.userId : namespace.orgId;
  const rows = db
    .prepare(`SELECT r.*, ? AS owner FROM repos r WHERE r.${column} = ? ORDER BY r.name COLLATE NOCASE`)
    .all(namespace.name, id);
  return {
    owner: { name: namespace.name, kind: namespace.kind },
    repositories: rows.filter((repo) => canViewRepo(db, user, repo)).map((repo) => serializeRepoSummary(db, repo)),
  };
}

/** Namespaces the signed-in user may create a repository in (REQ-3-2-1). */

