import { Link, useParams } from 'react-router-dom';
import { repo as repoCopy } from '../../contracts/copy';
import { repoApi } from './api';
import type { RepositorySummary } from './api';

/**
 * Repository list of one namespace (owner) — the "personal/organisation
 * Repositories list" entry point of REQ-3 and the destination of the owner link
 * in the repository header.
 *
 * It reads the same access rule as every other view, so a visitor only sees the
 * public repositories of the namespace.
 */
export function OwnerRepositoriesPage() {
  const params = useParams();
  const owner = params.owner ?? '';
  const [state, setState] = useState<{ loading: boolean; known: boolean; repositories: RepositorySummary[] }>({
    loading: true,
    known: true,
    repositories: [],
  });

  useEffect(() => {
    let active = true;
    setState({ loading: true, known: true, repositories: [] });
    repoApi
      .listByOwner(owner)
      .then((result) => {
        if (active) setState({ loading: false, known: result.owner !== null, repositories: result.repositories });
      })
      .catch(() => {
        if (active) setState({ loading: false, known: false, repositories: [] });
      });
    return () => {
      active = false;
    };
  }, [owner]);

  return (
    <div className="page-shell">
      <h1 className="page-title">{owner}</h1>
      <p className="text-muted mt-1">{repoCopy.repositories}</p>

      {state.loading ? <p className="text-muted mt-4">Loading…</p> : null}

      {!state.loading && state.repositories.length === 0 ? (
        <p className="text-muted mt-4">{state.known ? 'No repositories' : 'Not found'}</p>
      ) : null}

      {state.repositories.length > 0 ? (
        <ul className="mt-4 flex list-none flex-col gap-3 p-0">
          {state.repositories.map((repository) => (
            <li key={`${repository.owner}/${repository.name}`} className="app-card p-3">
              <h2 className="m-0 text-base font-600">
                <Link className="text-accent" to={repository.path}>
                  {repository.name}
                </Link>
              </h2>
              {repository.description ? <p className="m-0 mt-1 text-sm">{repository.description}</p> : null}
              <p className="m-0 mt-1 text-sm text-muted">
                {repository.visibility === 'public' ? repoCopy.publicBadge : repoCopy.privateBadge}
                {' · '}
                {repoCopy.updated(repository.updatedAt)}
              </p>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

export default OwnerRepositoriesPage;

