import { useState } from 'react';
import type { FormEvent } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { api, ApiError } from '../../api/client';
import { ErrorAlert, SuccessAlert } from '../../components/Alerts';
import { Button } from '../../components/Button';
import { TextField } from '../../components/TextField';
import { auth as authCopy, errors as errorCopy, VERIFICATION_CODE } from '../../contracts/copy';

/**
 * Account recovery (REQ-1-1-3).
 *
 * The step state lives in the URL (docs decision D3):
 *   /password-reset                    — step 1: "Email" + "Send reset link"
 *   /password-reset?step=2&email=…     — step 2: fixed code "123456" + reset form
 *   /password-reset?step=done          — success: "Password updated"
 *
 * Mounting any step sends no request, so refreshing never produces an email, a
 * link or a second account, and the visible result survives a reload.
 */
export function PasswordResetPage() {
  const [params] = useSearchParams();
  const step = params.get('step');
  const email = (params.get('email') ?? '').trim();

  if (step === 'done') return <ResetDoneStep />;
  if (step === '2' && email) return <ResetStep email={email.toLowerCase()} />;
  return <RequestStep />;
}

/** Step 1: ask for the email address. Registered and unknown emails behave the same. */
function RequestStep() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [error, setError] = useState<ApiError | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitting(true);
    setError(null);
    try {
      // Only the email format is validated server-side; both outcomes advance.
      await api.post('/api/auth/forgot-password', { email });
      navigate(`/password-reset?step=2&email=${encodeURIComponent(email.trim().toLowerCase())}`);
    } catch (caught) {
      setError(caught instanceof ApiError ? caught : new ApiError(0, { code: 'unknown', message: errorCopy.unknown }));
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="mx-auto w-full max-w-sm mt-10">
      <h1 className="page-title text-center">{authCopy.forgotPassword}</h1>

      <div className="app-card p-4 mt-4">
        {error ? <ErrorAlertList errors={error} /> : null}
        <form onSubmit={onSubmit} noValidate>
          <TextField
            label={authCopy.email}
            name="email"
            type="email"
            autoComplete="email"
            value={email}
            error={error?.fieldError('email')}
            onChange={(event) => setEmail(event.target.value)}
          />
          <Button type="submit" variant="primary" className="w-full" disabled={submitting}>
            {authCopy.sendResetLink}
          </Button>
        </form>

        <p className="mt-4 text-sm m-0">
          <Link className="text-accent" to="/login">
            {authCopy.signIn}
          </Link>
        </p>
      </div>
    </div>
  );
}

/**
 * Step 2: the fixed local demonstration code is shown as its own visible text
 * value (never embedded in a longer sentence), above the reset form.
 */
function ResetStep({ email }: { email: string }) {
  const navigate = useNavigate();
  const [code, setCode] = useState('');
  const [values, setValues] = useState({ newPassword: '', confirmPassword: '' });
  const [error, setError] = useState<ApiError | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const update = (field: 'newPassword' | 'confirmPassword', value: string) =>
    setValues((current) => ({ ...current, [field]: value }));

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitting(true);
    setError(null);
    try {
      await api.post('/api/auth/reset-password', {
        email,
        code,
        newPassword: values.newPassword,
        confirmPassword: values.confirmPassword,
      });
      navigate('/password-reset?step=done');
    } catch (caught) {
      const apiError =
        caught instanceof ApiError ? caught : new ApiError(0, { code: 'unknown', message: errorCopy.unknown });
      setError(apiError);
      // Submitted password values are never redisplayed (D9); the code keeps.
      setValues({ newPassword: '', confirmPassword: '' });
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="mx-auto w-full max-w-sm mt-10">
      <h1 className="page-title text-center">{authCopy.forgotPassword}</h1>

      <div className="app-card p-4 mt-4">
        <p className="text-sm text-muted m-0">Local demonstration verification code:</p>
        <p className="verification-code m-0 mt-1">{VERIFICATION_CODE}</p>

        {error ? (
          <div className="mt-3">
            <ErrorAlertList errors={error} />
          </div>
        ) : null}

        <form onSubmit={onSubmit} noValidate className="mt-2">
          <TextField
            label={authCopy.verificationCode}
            name="code"
            autoComplete="one-time-code"
            value={code}
            error={error?.fieldError('code')}
            onChange={(event) => setCode(event.target.value)}
          />
          <TextField
            label={authCopy.newPassword}
            name="newPassword"
            type="password"
            autoComplete="new-password"
            value={values.newPassword}
            error={error?.fieldError('newPassword')}
            onChange={(event) => update('newPassword', event.target.value)}
          />
          <TextField
            label={authCopy.confirmPassword}
            name="confirmPassword"
            type="password"
            autoComplete="new-password"
            value={values.confirmPassword}
            error={error?.fieldError('confirmPassword')}
            onChange={(event) => update('confirmPassword', event.target.value)}
          />
          <Button type="submit" variant="primary" className="w-full" disabled={submitting}>
            {authCopy.resetPassword}
          </Button>
        </form>
      </div>
    </div>
  );
}

/** Success step: the message is displayed in place; nothing else happens. */
function ResetDoneStep() {
  return (
    <div className="mx-auto w-full max-w-sm mt-10">
      <h1 className="page-title text-center">{authCopy.forgotPassword}</h1>

      <div className="app-card p-4 mt-4">
        <SuccessAlert>{errorCopy.passwordUpdated}</SuccessAlert>
        <p className="text-sm m-0">
          <Link className="text-accent" to="/login">
            {authCopy.signIn}
          </Link>
        </p>
      </div>
    </div>
  );
}

/** Field problems rendered next to their field; non-field ones above the form. */
function ErrorAlertList({ errors }: { errors: ApiError }) {
  const general = errors.generalErrors();
  return (
    <>
      {general.map((message) => (
        <ErrorAlert key={message}>{message}</ErrorAlert>
      ))}
    </>
  );
}

export default PasswordResetPage;

import { Link, Outlet } from 'react-router-dom';
import { auth as authCopy } from '../../contracts/copy';

/**
 * Settings layout (docs/architecture.md §7).
 *
 * "Password and authentication" (REQ-1-3) is the M1 page; the other entries are
 * placeholders owned by later modules and render a stable "coming later" panel.
 */
export function SettingsLayout() {
  return (
    <div className="page-shell">
      <h1 className="page-title">{authCopy.settings}</h1>

      <div className="mt-4 flex flex-col md:flex-row gap-4">
        <nav className="md:w-56 shrink-0 flex flex-col gap-1 text-sm" aria-label={authCopy.settings}>
          <Link className="menu-item" to="/settings/profile">
            Public profile
          </Link>
          <Link className="menu-item" to="/settings/password">
            {authCopy.passwordAndAuthentication}
          </Link>
        </nav>
        <section className="flex-1 min-w-0">
          <Outlet />
        </section>
      </div>
    </div>
  );
}

/** Placeholder panel for settings sections owned by later modules. */
export function SettingsPlaceholder({ section }: { section: string }) {
  return (
    <div className="app-card p-4">
      <h2 className="section-title m-0 mt-0">{section}</h2>
      <p className="text-sm text-muted m-0">This settings section is provided by a later module.</p>
    </div>
  );
}

export default SettingsLayout;

import { useState } from 'react';
import type { FormEvent } from 'react';
import { api, ApiError } from '../../api/client';
import { SuccessAlert } from '../../components/Alerts';
import { Button } from '../../components/Button';
import { TextField } from '../../components/TextField';
import { auth as authCopy, errors as errorCopy } from '../../contracts/copy';

/**
 * "Password and authentication" security form (REQ-1-3).
 *
 * Every field problem of one submission is rendered beside its field; after a
 * failure no password value is redisplayed. A successful update shows
 * "Password updated" in place and clears the form.
 */
export function PasswordSettingsPage() {
  const [values, setValues] = useState({ currentPassword: '', newPassword: '', confirmPassword: '' });
  const [error, setError] = useState<ApiError | null>(null);
  const [updated, setUpdated] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const update = (field: keyof typeof values, value: string) =>
    setValues((current) => ({ ...current, [field]: value }));

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitting(true);
    setError(null);
    setUpdated(false);
    try {
      await api.post('/api/auth/change-password', values);
      setUpdated(true);
      setValues({ currentPassword: '', newPassword: '', confirmPassword: '' });
    } catch (caught) {
      setError(caught instanceof ApiError ? caught : new ApiError(0, { code: 'unknown', message: errorCopy.unknown }));
      // Password values are never redisplayed after a failed submission.
      setValues({ currentPassword: '', newPassword: '', confirmPassword: '' });
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div>
      <h2 className="section-title mt-0">{authCopy.passwordAndAuthentication}</h2>

      <div className="app-card p-4">
        {updated ? <SuccessAlert>{errorCopy.passwordUpdated}</SuccessAlert> : null}

        <form onSubmit={onSubmit} noValidate>
          <TextField
            label={authCopy.currentPassword}
            name="currentPassword"
            type="password"
            autoComplete="current-password"
            value={values.currentPassword}
            error={error?.fieldError('currentPassword')}
            onChange={(event) => update('currentPassword', event.target.value)}
          />
          <TextField
            label={authCopy.newPassword}
            name="newPassword"
            type="password"
            autoComplete="new-password"
            help="12–128 characters with upper case, lower case, a digit and a special character."
            value={values.newPassword}
            error={error?.fieldError('newPassword')}
            onChange={(event) => update('newPassword', event.target.value)}
          />
          <TextField
            label={authCopy.confirmPassword}
            name="confirmPassword"
            type="password"
            autoComplete="new-password"
            value={values.confirmPassword}
            error={error?.fieldError('confirmPassword')}
            onChange={(event) => update('confirmPassword', event.target.value)}
          />
          <Button type="submit" variant="primary" disabled={submitting}>
            {authCopy.updatePassword}
          </Button>
        </form>
      </div>
    </div>
  );
}

export default PasswordSettingsPage;

import { Route, Routes } from 'react-router-dom';
import { RequireAuth } from './components/RequireAuth';
import { HomePage } from './features/home/HomePage';
import { SignInPage } from './features/auth/SignInPage';
import { SignUpPage } from './features/auth/SignUpPage';
import { PasswordResetPage } from './features/auth/PasswordResetPage';
import { SearchPage } from './features/search/SearchPage';
import { PasswordSettingsPage } from './features/settings/PasswordSettingsPage';
import { SettingsLayout, SettingsPlaceholder } from './features/settings/SettingsLayout';
import { NotFoundPage } from './features/NotFoundPage';

/**
 * Application routes (docs/architecture.md §7).
 *
 * Business modules add their routes here:
 *   /:owner/:repo(/*)  — M3/M4/M5/M6
 *   /orgs/:org(/*)     — M2
 *   /settings/*        — M1 provides the layout and the password page; the
 *                        remaining sections are placeholders for later modules.
 */
export const appRoutes = (
  <Routes>
    <Route path="/" element={<HomePage />} />
    <Route path="/login" element={<SignInPage />} />
    <Route path="/register" element={<SignUpPage />} />
    <Route path="/password-reset" element={<PasswordResetPage />} />
    <Route path="/search" element={<SearchPage />} />
    <Route
      path="/settings"
      element={
        <RequireAuth>
          <SettingsLayout />
        </RequireAuth>
      }
    >
      <Route index element={<SettingsPlaceholder section="Public profile" />} />
      <Route path="profile" element={<SettingsPlaceholder section="Public profile" />} />
      <Route path="password" element={<PasswordSettingsPage />} />
      <Route path="organizations" element={<SettingsPlaceholder section="Organizations" />} />
      <Route path="repositories" element={<SettingsPlaceholder section="Repositories" />} />
    </Route>
    <Route path="*" element={<NotFoundPage />} />
  </Routes>
);

export default appRoutes;
